  builder_.add_RECHECK_NOTES(RECHECK_NOTES);
  builder_.add_SECONDARY_THREATS_INTRODUCED(SECONDARY_THREATS_INTRODUCED);
  builder_.add_CONFLICTS_WITH_COA_IDS(CONFLICTS_WITH_COA_IDS);
  builder_.add_GROUP_ID(GROUP_ID);
  builder_.add_NORAD_CAT_ID(NORAD_CAT_ID);
  builder_.add_THREAT_REF(THREAT_REF);
  builder_.add_CREATED_UTC(CREATED_UTC);
