  builder_.add_RECHECK_STATUS(RECHECK_STATUS);
  builder_.add_RECHECKED(RECHECKED);
  builder_.add_RESIDUAL_TIER(RESIDUAL_TIER);
  builder_.add_ACTION_KIND(ACTION_KIND);
